#!/usr/bin/env python3
"""Спрайты пехотных пушек (DarkestHour): лафет со щитом и стволом (вид сверху, ствол на юг — поворачивается
с сущностью), снаряды 75/90 мм, снаряд в полёте.

Запуск из корня репозитория:  python3 Tools/_DarkestHour/field_guns/build.py
"""
import json
import os

from PIL import Image, ImageDraw

ROOT = 'Resources/Textures/_DarkestHour/Objects/Weapons/FieldGuns'
META = {'version': 1, 'license': 'CC-BY-SA-3.0',
        'copyright': 'DarkestHour, generated by Tools/_DarkestHour/field_guns/build.py'}


def shade(c, k):
    return tuple(max(0, min(255, int(v * k))) for v in c[:3]) + (255,)


def save_rsi(name, size, states):
    path = os.path.join(ROOT, name + '.rsi')
    os.makedirs(path, exist_ok=True)
    meta = dict(META, size={'x': size, 'y': size}, states=[])
    for state, img in states:
        img.save(os.path.join(path, state + '.png'))
        meta['states'].append({'name': state})
    with open(os.path.join(path, 'meta.json'), 'w') as f:
        json.dump(meta, f)
        f.write('\n')
    print(path)


def gun(paint, barrel_len, barrel_w, shield_w, deployed):
    """Вид сверху, 64x64, центр — ось колёс. Ствол на юг (вниз), станины — на север."""
    s = 64
    im = Image.new('RGBA', (s, s), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    cx, cy = 32, 30
    dark, light = shade(paint, 0.6), shade(paint, 1.25)
    # станины: разведены (боевое положение) или сведены (походное)
    spread = 10 if deployed else 3
    for side in (-1, 1):
        x0 = cx + side * 3
        x1 = cx + side * (3 + spread)
        d.polygon([(x0 - 2, cy), (x0 + 2, cy), (x1 + 2, cy - 26), (x1 - 2, cy - 26)], fill=dark)
        d.line([(x0, cy), (x1, cy - 26)], fill=paint, width=1)
        d.rectangle([x1 - 3, cy - 29, x1 + 3, cy - 26], fill=shade(paint, 0.45))  # сошники
    # колёса
    for side in (-1, 1):
        wx = cx + side * (shield_w // 2 + 2)
        d.rectangle([wx - 3, cy - 6, wx + 3, cy + 6], fill=(28, 28, 30, 255))
        d.line([(wx - 3, cy), (wx + 3, cy)], fill=(70, 70, 74, 255))
    # щит
    d.rectangle([cx - shield_w // 2, cy + 1, cx + shield_w // 2, cy + 5], fill=paint, outline=dark)
    d.line([(cx - shield_w // 2 + 1, cy + 2), (cx + shield_w // 2 - 1, cy + 2)], fill=light)
    # люлька и ствол
    d.rectangle([cx - barrel_w, cy - 6, cx + barrel_w, cy + 6], fill=dark)
    d.rectangle([cx - barrel_w // 2 - 1, cy + 6, cx + barrel_w // 2 + 1, cy + 6 + barrel_len], fill=shade(paint, 0.8))
    d.line([(cx - barrel_w // 2, cy + 6), (cx - barrel_w // 2, cy + 6 + barrel_len)], fill=light)
    # дульный тормоз
    d.rectangle([cx - barrel_w // 2 - 2, cy + 4 + barrel_len, cx + barrel_w // 2 + 2, cy + 8 + barrel_len],
                fill=shade(paint, 0.5))
    # казённик
    d.rectangle([cx - barrel_w // 2 - 1, cy - 10, cx + barrel_w // 2 + 1, cy - 6], fill=shade(paint, 0.5))
    return im


def shell(body, band, tip, sabot=False):
    """Снаряд с гильзой, 32x32, лёжа по диагонали."""
    im = Image.new('RGBA', (32, 32), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    brass = (176, 140, 64, 255)
    # гильза
    d.polygon([(5, 25), (9, 29), (17, 21), (13, 17)], fill=brass)
    d.line([(5, 25), (13, 17)], fill=shade(brass, 1.25))
    d.polygon([(4, 26), (6, 28), (8, 30), (3, 27)], fill=shade(brass, 0.7))
    if sabot:
        # подкалиберный: тонкий сердечник с поддоном
        d.polygon([(13, 17), (17, 21), (19, 19), (15, 15)], fill=(60, 60, 64, 255))
        d.line([(16, 17), (27, 6)], fill=(40, 40, 44, 255), width=3)
        d.line([(16, 16), (26, 6)], fill=(110, 110, 116, 255))
        d.polygon([(26, 5), (29, 3), (28, 7)], fill=tip)
    else:
        d.polygon([(13, 17), (17, 21), (24, 14), (20, 10)], fill=body)
        d.line([(13, 17), (20, 10)], fill=shade(body, 1.3))
        d.polygon([(15, 19), (17, 21), (19, 19), (17, 17)], fill=band)
        d.polygon([(20, 10), (24, 14), (28, 6), (26, 4)], fill=shade(body, 0.85))
        d.polygon([(26, 4), (28, 6), (29, 3)], fill=tip)
    return im


def flight():
    im = Image.new('RGBA', (32, 32), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    d.rectangle([14, 8, 17, 22], fill=(70, 70, 66, 255))
    d.polygon([(14, 22), (17, 22), (15, 26)], fill=(50, 50, 50, 255))
    d.rectangle([14, 4, 17, 8], fill=(255, 200, 120, 160))  # трассер
    return im


if __name__ == '__main__':
    imperial = (118, 122, 128, 255)
    republic = (150, 136, 92, 255)
    save_rsi('field_gun_75', 64, [('deployed', gun(imperial, 20, 4, 18, True)),
                                  ('folded', gun(imperial, 20, 4, 18, False))])
    save_rsi('field_gun_90', 64, [('deployed', gun(republic, 23, 5, 22, True)),
                                  ('folded', gun(republic, 23, 5, 22, False))])
    olive = (86, 96, 62, 255)
    save_rsi('shells', 32, [
        ('he', shell(olive, (214, 176, 46, 255), (200, 200, 200, 255))),
        ('incendiary', shell(olive, (190, 50, 40, 255), (200, 120, 40, 255))),
        ('apfsds', shell(olive, (0, 0, 0, 255), (220, 220, 230, 255), sabot=True)),
        ('flight', flight()),
    ])
